import{_ as n,o as a,c as i,a5 as e}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Task và Approval — phương án đơn giản hóa","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/task-approval-simplification/spec.md","filePath":"feature/content-task-workflow/task-approval-simplification/spec.md"}'),h={name:"feature/content-task-workflow/task-approval-simplification/spec.md"};function r(c,t,o,l,u,s){return a(),i("div",null,[...t[0]||(t[0]=[e('<p>&gt; <strong>SUPERSEDED for new implementation — 2026-10-18:</strong> tài liệu này giữ lịch sử đề xuất ngày 16/10, không dùng làm checklist hiện hành hoặc lệnh APPLY. Xem <a href="./../3-6-9-approval-sequence-creator-manager-client/spec.html">spec FR3.6.9 v3</a>, <a href="./../3-6-9-approval-sequence-creator-manager-client/plan.html">plan</a>, <a href="./../3-6-9-approval-sequence-creator-manager-client/task.html">task</a>, <a href="./../3-6-9-approval-sequence-creator-manager-client/test.html">test</a>. Đã chốt /editor, một bản hiện tại không review snapshots, withdraw trước Manager decision và một Client bất kỳ. Task structure đã triển khai riêng; Approval mới hoàn thành tài liệu giai đoạn 1.</p><p>&gt; Checkpoint 2026-10-17 (historical): Task structure removal of QC/plannedPublishAt and Atlas metadata APPLY were implemented separately; earlier inventory/results below are dated history, not current-state evidence.</p><h1 id="task-va-approval-—-phuong-an-đon-gian-hoa" tabindex="-1">Task và Approval — phương án đơn giản hóa <a class="header-anchor" href="#task-va-approval-—-phuong-an-đon-gian-hoa" aria-label="Permalink to &quot;Task và Approval — phương án đơn giản hóa&quot;">​</a></h1><p>Ngày: 2026-10-16. Trạng thái: <strong>DRAFT — chờ team review, chưa triển khai thay đổi này</strong>.</p><p>Phạm vi: FR 3.6.1/3.6.2 (DA-978), FR 3.6.9 (DA-E51-03). Người dùng xác nhận tiếp nhận FR 3.6.9 từ Phước; cần đồng bộ phân công trên Jira/master plan với team. Không tự tuyên bố Jira đã cập nhật.</p><h2 id="_1-nguon-va-thu-tu-uu-tien" tabindex="-1">1. Nguồn và thứ tự ưu tiên <a class="header-anchor" href="#_1-nguon-va-thu-tu-uu-tien" aria-label="Permalink to &quot;1. Nguồn và thứ tự ưu tiên&quot;">​</a></h2><ul><li>Quyết định người dùng trong trao đổi ngày 2026-10-16 được ghi lại bên dưới để team review.</li><li><a href="./../../../ba/05-content-task-workflow.html">BA Task</a>, <a href="./../../../ba/12-state-machines.html">state machines</a>, <a href="./../3-6-9-approval-sequence-creator-manager-client/spec.html">spec Approval cũ</a>, <a href="./../task-workflow-contract.html">contract hiện có</a>.</li><li><a href="./../../../team_guide.html">Team guide</a>, <a href="./../../../rule/feature-workflow.html">quy trình feature</a>.</li><li>Tài liệu cũ còn QC/ngày đăng dự kiến; KHÔNG tự sửa tài liệu chung hoặc coi code hiện tại đã đáp ứng phương án này. Sau review phải đồng bộ nguồn BA/spec chung trước implement.</li></ul><h2 id="_2-quyet-đinh-đa-chot" tabindex="-1">2. Quyết định đã chốt <a class="header-anchor" href="#_2-quyet-đinh-đa-chot" aria-label="Permalink to &quot;2. Quyết định đã chốt&quot;">​</a></h2><ul><li>Giữ một workflow Task chung cho POST, LIVESTREAM, SURVEY, EVENT_PLAN, PRESS_RECOMMENDATION; tích hợp nội dung POST trước, các loại khác phối hợp chủ module.</li><li>Giữ 5 trạng thái: TODO / IN_PROGRESS / IN_REVIEW / FINISHED / CANCELLED. reviewStep tách riêng, luồng mới chỉ MANAGER → CLIENT nếu requiresClientApproval=true.</li><li>Bỏ review chéo/QC trong luồng mới. Không đổi role hệ thống, không xóa lịch sử QC cũ.</li><li>Chỉ Creator được giao bấm bắt đầu. Sau lần bắt đầu đầu tiên Manager không sửa brief/deadline/giao lại; reject không mở khóa các quyền này.</li><li>Reject bắt buộc lý do, Task về IN_PROGRESS; gửi lại duyệt từ Manager. Bước cuối approve mới FINISHED; chưa hỗ trợ mở lại FINISHED.</li><li>Giữ dueDate dạng dữ liệu có cấu trúc và workflowRevision chống xung đột. Bỏ plannedPublishAt khỏi nghiệp vụ mới; description chứa yêu cầu chi tiết, kể cả hướng dẫn thời điểm đăng nếu cần. Không suy dueDate bằng cách parse description.</li><li>Task POST liên kết tối đa một Post; chưa tạo nội dung thì có thể chưa có Post. Post độc lập vẫn được giữ. Các loại content khác liên kết Task ở module tương ứng, không ép tất cả thành Post.</li><li>task_approvals lưu từng quyết định APPROVE/REJECT, nhóm theo taskId + approvalRound. Không tạo sẵn quyết định cho người chưa duyệt. Một lượt có tối đa 2 quyết định trong luồng hiện tại.</li><li>Nhận xét về nội dung khi duyệt khác bình luận công việc: quyết định duyệt lưu ở task_approvals; trao đổi Task thuộc task_comments/FR 3.6.3, không thay thế lẫn nhau.</li><li>Thông báo trong ứng dụng: chuyển bước gửi người duyệt tiếp theo; reject gửi Creator. Không thêm email.</li><li>FINISHED không tự publish. Không thay Editor/Content Writing, AI, publishing Facebook/RabbitMQ của thành viên khác.</li></ul><h2 id="_3-entity-task-đich" tabindex="-1">3. Entity Task đích <a class="header-anchor" href="#_3-entity-task-đich" aria-label="Permalink to &quot;3. Entity Task đích&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nhóm</th><th>Field giữ lại</th></tr></thead><tbody><tr><td>Định danh/phạm vi</td><td>_id, workspaceId, campaignId, campaignWorkItemId</td></tr><tr><td>Yêu cầu</td><td>type, name, description, dueDate, inputReferences</td></tr><tr><td>Giao việc</td><td>assigneeId, requiresClientApproval, assignedBy, assignedAt</td></tr><tr><td>Workflow</td><td>status, reviewStep, approvalRound, workflowRevision</td></tr><tr><td>Nguồn</td><td>sourceType, sourceRefId, typeMetadata</td></tr><tr><td>Audit</td><td>firstStartedBy, firstStartedAt, cancellation, createdBy, createdAt, updatedAt</td></tr></tbody></table><p>plannedPublishAt, qcAssigneeId, detailIdentifiedAt/By là field legacy/deprecated, không dùng trong UI/luồng mới. Deprecate không đồng nghĩa xóa vật lý ngay. reviewStep phải trống ngoài IN_REVIEW ở writer mới; legacy thiếu dữ liệu được kiểm kê riêng.</p><p>task_approvals giữ _id, taskId, approvalRound, step, action, actorId, nhận xét duyệt, createdAt. Tên nhận xét hiện là comment; đề xuất reviewNote để rõ nghĩa nhưng cần team chốt tên contract trước migration rename. Không đổi tên collection.</p><h2 id="_4-nhung-điem-chua-chot-hoan" tabindex="-1">4. Những điểm CHƯA chốt / hoãn <a class="header-anchor" href="#_4-nhung-điem-chua-chot-hoan" aria-label="Permalink to &quot;4. Những điểm CHƯA chốt / hoãn&quot;">​</a></h2><ul><li>Snapshot: Q2 trước đó đã chọn duyệt snapshot. Sau đó người dùng yêu cầu TẠM HOÃN quyết định/triển khai snapshot vì Content Writing do thành viên khác phụ trách. Không coi đây là quyết định bỏ snapshot hoặc đổi sang duyệt live content.</li><li>Không thêm snapshotId/reviewContentVersion vào Task/Approval trong đợt chuẩn bị DB này; không chạy migration post_versions chỉ vì kế hoạch này. Cơ chế đóng băng/phiên bản nội dung phải được phối hợp trước nghiệm thu Approval end-to-end.</li><li>Thu hồi: đã nêu nhu cầu ở Q3 nhưng quyền, thời điểm và điều kiện chưa chốt. Chưa bổ sung action SUBMIT/WITHDRAW vào task_approvals trong thiết kế đợt này. Submit API tương lai có thể tăng lượt/cập nhật Task mà không tạo row quyết định.</li><li>Legacy: chưa có phê duyệt chuyển Task đang QC hoặc thiếu reviewStep về IN_PROGRESS hay sang MANAGER. Cần allowlist/đề xuất riêng, không tự backfill lịch sử bắt đầu.</li><li>Định dạng content/snapshot của Livestream/Survey/Event do module phụ trách thống nhất; EVENT_PLAN chỉ bàn giao kế hoạch, không thêm vận hành sự kiện.</li></ul><h2 id="_5-đieu-kien-review" tabindex="-1">5. Điều kiện review <a class="header-anchor" href="#_5-đieu-kien-review" aria-label="Permalink to &quot;5. Điều kiện review&quot;">​</a></h2><p>Team xác nhận phạm vi/contract với Phước và chủ Content Writing; rà soát nguồn BA chung; chốt reviewNote hay giữ comment; chốt xử lý dữ liệu cũ. Chưa đóng FR hoặc coi DB migration là hoàn thành chức năng duyệt.</p>',17)])])}const d=n(h,[["render",r]]);export{p as __pageData,d as default};
